  const CampusPlace({
    required this.name,
    required this.latitude,
    required this.longitude,
    required this.category,
    this.osmId = '',
    this.nameEn = '',
  });

  final String name;
  final double latitude;
  final double longitude;
  final CampusCategory category;

  /// `node/123` or `way/456`; empty when OSM gave none.
  final String osmId;

  /// The English name when OSM carries one, else empty.
  final String nameEn;

  String? get osmUrl =>
      osmId.isEmpty ? null : 'https://www.openstreetmap.org/$osmId';
}

